714	function computePresetDate(preset: PresetTask, show: Show): { date: string; requires: unknown } {
715	  if (!preset.dueDateOffset || !preset.dueDateUnit || !preset.dueDateDirection || !preset.dueDateAnchor) {
716	    return { date: "", requires: true };
717	  }
718	  const anchor = (show as unknown as Record<string, unknown>)[preset.dueDateAnchor];
719	  if (!anchor) return { date: "", requires: null };
720	  const anchorDate = parseDateStr(anchor as string);
721	  const d =
722	    preset.dueDateDirection === "before"
723	      ? preset.dueDateUnit === "biz"
724	        ? subBusinessDays(anchorDate, preset.dueDateOffset)
725	        : subDays(anchorDate, preset.dueDateOffset)
726	      : preset.dueDateUnit === "biz"
727	        ? addBusinessDays(anchorDate, preset.dueDateOffset)
728	        : addDays(anchorDate, preset.dueDateOffset);
729	  return { date: format(d, "yyyy-MM-dd"), requires: anchor };
730	}
731	
732	function presetRuleLabel(preset: PresetTask): string {
733	  if (!preset.dueDateOffset) return "Manual entry — set due date after adding";
734	  const anchor = ANCHOR_DISPLAY[preset.dueDateAnchor!] ?? preset.dueDateAnchor ?? "";
735	  return `${preset.dueDateOffset} ${preset.dueDateUnit} days ${preset.dueDateDirection} ${anchor}`;
736	}
